"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["75212"],{8680(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.criterio_obrigatorio","status":422,"titulo":"A delibera\xe7\xe3o colegiada declara o crit\xe9rio de vota\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.banca.criterio_obrigatorio","requisitos":["UNI-REQ-0275"],"oQueAconteceu":["A recusa tamb\xe9m ocorre quando o c\xf3digo informado n\xe3o corresponde a uma das op\xe7\xf5es aceitas.","A banca declarada com delibera\xe7\xe3o por vota\xe7\xe3o (`COLEGIADA_COM_VOTACAO`) n\xe3o traz o\\ncrit\xe9rio de decis\xe3o. O edital define, para cada banca, o crit\xe9rio pelo qual a\\nvota\xe7\xe3o decide (UNI-REQ-0275), e o sistema n\xe3o escolhe um no lugar dele.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.criterio` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.criterio` na banca da etapa."],"comoResolver":["Informe no campo `criterio` o crit\xe9rio do edital: `MAIORIA_SIMPLES`,\\n`MAIORIA_ABSOLUTA` ou `UNANIMIDADE`. Conforme o crit\xe9rio, outros campos passam a\\nser exigidos ou recusados: o\\n[desempate](/erros/uniplus.selecao.banca.desempate_obrigatorio) na maioria e o\\n[valor para a unanimidade n\xe3o alcan\xe7ada](/erros/uniplus.selecao.banca.sem_unanimidade_obrigatoria)\\nna unanimidade."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);